from __future__ import annotations

import json
import re
import sys
from decimal import Decimal, ROUND_HALF_UP


def money(value: str) -> float:
    return float(Decimal(value).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))


def extract(input_path: str, output_path: str) -> None:
    lines = open(input_path, encoding="utf-8").read().splitlines()
    result = {"invoice_number": "", "invoice_date": "", "currency": "",
              "subtotal": 0.0, "tax": 0.0, "total": 0.0, "line_items": []}
    item_pattern = re.compile(r"^\s*(.+?)\s{2,}(\d+)\s+(\d+\.\d{2})\s+(\d+\.\d{2})\s*$")
    for line in lines:
        if line.startswith("INVOICE:"):
            result["invoice_number"] = line.split(":", 1)[1].strip()
        elif line.startswith("DATE:"):
            result["invoice_date"] = line.split(":", 1)[1].strip()
        elif line.startswith("CURRENCY:"):
            result["currency"] = line.split(":", 1)[1].strip()
        elif line.startswith("SUBTOTAL:"):
            result["subtotal"] = money(line.split(":", 1)[1].strip())
        elif line.startswith("TAX:"):
            result["tax"] = money(line.split(":", 1)[1].strip())
        elif line.startswith("TOTAL:"):
            result["total"] = money(line.split(":", 1)[1].strip())
        else:
            match = item_pattern.match(line)
            if match and match.group(1).strip() != "DESCRIPTION":
                result["line_items"].append({
                    "description": match.group(1).strip(),
                    "quantity": int(match.group(2)),
                    "unit_price": money(match.group(3)),
                    "amount": money(match.group(4)),
                })
    with open(output_path, "w", encoding="utf-8") as stream:
        json.dump(result, stream, ensure_ascii=False, sort_keys=True)


if __name__ == "__main__":
    extract(sys.argv[1], sys.argv[2])
